# Classify all generated encoder outputs concisely, looking specifically for first MSan reports involving SAO.
cmd = r'''
python3 - <<'PY'
import glob, subprocess, os, re, sys, json, collections
files=[f for f in sorted(glob.glob('/workspace/enc_tests/*.265')) if os.path.getsize(f)>0]
print('nonzero files', len(files))
counts=collections.Counter(); candidates=[]; func_examples={}
for idx,f in enumerate(files):
    env=os.environ.copy(); env['MSAN_OPTIONS']='halt_on_error=1:exit_code=86:report_umrs=1:symbolize=1:track_origins=2'
    try:
        p=subprocess.run(['/workspace/msan_out/hevc_dec_fuzzer', f], stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, timeout=12)
        out=(p.stdout+p.stderr).decode('latin1','replace')
    except subprocess.TimeoutExpired:
        func='TIMEOUT'; out=''; p=type('P',(),{'returncode':124})()
    m=re.search(r'#0 0x[0-9a-f]+ in ([^ \n]+)', out)
    func=m.group(1) if m else ('OK' if p.returncode==0 else 'RC'+str(p.returncode))
    origin=''
    mo=re.search(r"created by an allocation of '([^']+)' in the stack frame of function '([^']+)'", out)
    if mo: origin=mo.group(1)+'@'+mo.group(2)
    stack_sao=('ihevcd_sao_shift_ctb' in out) or ('ihevc_sao_' in out) or ('sao' in func.lower())
    key=(func, origin, 'SAO' if stack_sao else '')
    counts[key]+=1
    func_examples.setdefault(key, f)
    if stack_sao:
        candidates.append((f, os.path.getsize(f), p.returncode, func, origin, out[:4000]))
print('counts:')
for (func,origin,tag),cnt in counts.most_common():
    print(cnt, func, origin, tag, os.path.basename(func_examples[(func,origin,tag)]))
print('\nSAO candidates', len(candidates))
for c in candidates[:50]:
    print('---', os.path.basename(c[0]), 'size', c[1], 'rc', c[2], 'func', c[3], 'origin', c[4])
    # print first relevant lines
    for line in c[5].splitlines():
        if 'WARNING' in line or '#0' in line or '#1' in line or '#2' in line or 'sao' in line.lower() or 'origin' in line.lower() or 'created by' in line:
            print(line[:240])
PY
'''
res = await self.shell.run(cmd, timeout=900)
print(res.text[:60000])
